#include <array>
#include <iostream>

int main() {
    std::array<int, 10> count{};
    char c;
    while (std::cin.get(c)) {
        if (c >= '0' && c <= '9') {
            count[static_cast<std::size_t>(c - '0')]++;
        }
    }
    bool any = false;
    for (std::size_t d = 0; d < count.size(); d++) {
        if (count[d] > 0) {
            std::cout << d << ": " << count[d] << '\n';
            any = true;
        }
    }
    if (!any) {
        std::cout << "цифр нет\n";
    }
    return 0;
}

