#include <iomanip>
#include <iostream>

double average(int values[]) {
    int n = static_cast<int>(sizeof(values) / sizeof(values[0]));
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        sum += values[i];
    }
    return static_cast<double>(sum) / n;
}

int main() {
    int values[6];
    for (int i = 0; i < 6; i++) {
        std::cin >> values[i];
    }
    std::cout << std::fixed << std::setprecision(2) << average(values) << '\n';
    return 0;
}

